function getTokenPrice(address priceAggregatorAddress, uint256 maxTimeout, uint256 lookback) internal view returns (uint256 price) {
    return
        lookback > 0
            ? getPrice(priceAggregatorAddress, maxTimeout)   // instantaneous -- WRONG branch
            : getTwap(priceAggregatorAddress, maxTimeout, lookback); // TWAP with lookback==0
}

if (token == C.WSTETH) {
    uint256 wstethUsdPrice = LibWstethUsdOracle.getWstethUsdPrice(0); // <-- ignores `lookback`
    if (wstethUsdPrice == 0) return 0;
    return wstethUsdPrice;
}

while (timestamp > t.endTimestamp) {
    t.cumulativePrice = t.cumulativePrice.add(uint256(answer).mul(t.lastTimestamp.sub(timestamp)));
    roundId -= 1;                       // naive decrement; breaks across phase boundary
    t.lastTimestamp = timestamp;
    (answer, timestamp) = getRoundData(priceAggregator, roundId);
    if (checkForInvalidTimestampOrAnswer(timestamp, answer, t.lastTimestamp, maxTimeout)) {
        return 0;                       // one bad round -> whole TWAP returns 0
    }
}
